			Transform parent = this.FindDeep("Sections", true).transform;
			resourceLoader.LoadScenePrefabs(ContestDataConstants.PREFAB_AB_NAME, parent, (name, result) =>
			{
				if (name == ContestDataConstants.OPENING_PREFAB_NAME)
					openingSection = result.GetComponent<OpeningSection>();
				else if (name == ContestDataConstants.VISUAL_PREFAB_NAME)
					visualSection = result.GetComponent<VisualSection>();
				else if (name == ContestDataConstants.DANCE_PREFAB_NAME)
					danceSection = result.GetComponent<DanceSection>();
				else if (name == ContestDataConstants.RESULT_PREFAB_NAME)
