				ContestUtils.EmitLog("Load failed!!!! sceneUISpriteAtlas", LogType.Error);
		}
		private void SceneInitialize() {
			ContestSoundPlayer.CreateInstance();
			currentSectionID = SectionID.Opening;
			SceneConnector connector = GameManager.connector;
			connector.ClearCharacterCache();
			// shipped: the count comes from the connector's character cache, the destroyed children from this transform
			int childCount = connector.characterCacheObjects.childCount;
			for (int i = 0; i < childCount; i++)
				UnityEngine.Object.Destroy(transform.GetChild(i).gameObject);

			objectManagerPtr.SetMainCamera(connector.mainCamera, wazaCamera);
			objectManagerPtr.SetEnvController(connector.environmentController);
			dataModel.Initialize();
			resourceLoader.Initialize();
			InitMultiMode();
		}
