			{
				if (result is ContestSettings contestSettings)
					objectManagerPtr.SetScriptableObject(contestSettings);
				else if (result is DanceSettings danceSettings)
					danceSection.SetScriptableObject(danceSettings);
				else if (result is ResultSettings resultSettings)
					resultSection.SetScriptableObject(resultSettings);
			});
			resourceLoader.RequestLoadAsset();
			while (resourceLoader.Loading)
				yield return null;
		}
