		private void PrevSetup() {
			objectManagerPtr.Setup();
			openingSection.Setup();
			visualSection.Setup(dataModel.GetMainBgmEventID(), contestViewSystem);
			resultSection.Setup(dataModel.IsTutorial);
			// danceSection is loaded only after the inlined GetProgressIconSpr (01c6776c) -> local
			Sprite iconSpr = dataModel.GetProgressIconSpr();
			danceSection.SetProgressIconSpr(iconSpr);
		}
		private global::System.Collections.IEnumerator IE_Start() {
			LoadWazaSequence();
			while (!openingSection.IsReady)
				yield return null;

			yield return Dpr.Battle.FrameCountTypeExtensions.GetYieldInstruction(Dpr.Battle.FrameCountType.EndOfFrame);

			Sequencer.update -= OnUpdate;
			Sequencer.update += OnUpdate;
			Sequencer.lateUpdate -= OnLateUpdate;
			Sequencer.lateUpdate += OnLateUpdate;
			yield return null;

			StartContest();
			while (!wazaViewSystem.IsReady)
			{
				wazaViewSystem.OnUpdate(Time.deltaTime);
				yield return null;
			}

			AfterSetup();
		}
		private void AfterSetup() {
			dataModel.SetSkillAnimDuration(wazaViewSystem.MaxTime);
			danceSection.Setup(dataModel, dataModel.IsTutorial);
			SetupNetwork();
			if (dataModel.IsTutorial)
				wazaViewSystem.SetCanOpenMsgWindowFlag(false);
		}
		private void OnDestroy() {
			network.OnFinalize();
			Sequencer.update -= OnUpdate;
			Sequencer.lateUpdate -= OnLateUpdate;
			Dpr.Battle.View.BattleViewAssetManager.UnInitialize(true);
			openingSection.OnFinalize();
			danceSection.OnFinalize();
			resultSection.OnFinalize();
			resourceLoader.OnFinalize();
			dataModel.OnFinalize();
			contestViewSystem.OnFinalize();
			wazaViewSystem.OnFinalize();
			dataModel.ResetQuaritySettings();
		}
		private void StartContest() {
