		private void OnUpdate(float deltaTime) {
#if !SWITCH
			// PC layer (s47): the contest runs on the BGM's play position (UpdateSection below) - fast-forward holds at 1x
			PcPlatform.PcGameSpeed.RequireNormalSpeed();
