			contestViewSystem.OnUpdate(deltaTime);
			wazaViewSystem.OnUpdate(deltaTime);
			if (IsCompleteSection)
			{
				FinishedContest();
				return;
			}
			UpdateSection(deltaTime, ContestSoundPlayer.player.GetBGMPlayPosition());
		}
		private void FinishedContest() {
