		private void UpdateSection(float deltaTime, float elapsedTime) {
			switch (currentSectionID)
			{
				case SectionID.Opening:
					UpdateOpeningSection();
					break;
				case SectionID.Visual:
					UpdateVisualSection();
					break;
				case SectionID.Dance:
					UpdateDanceSection(deltaTime, elapsedTime);
					break;
				case SectionID.WaitAsync:
					UpdateWaitAsync();
					break;
				case SectionID.Result:
					UpdateResultSection(deltaTime);
					break;
				case SectionID.NetworkError:
					UpdateNetworkError();
					break;
			}
		}
		private void UpdateOpeningSection() {
			if (!openingSection.UpdateSection() && danceSection.IsReady() && wazaViewSystem.IsReady && contestViewSystem.IsReady && objectManagerPtr.IsReady)
				RequestChangeSectionId(SectionID.Visual);
		}
		private void UpdateVisualSection() {
			if (visualSection.UpdateSection())
				return;

			RequestChangeSectionId(SectionID.Dance);
		}
		private void UpdateDanceSection(float deltaTime, float elapsedTime) {
			if (danceSection.UpdateSection(deltaTime, elapsedTime))
			{
				if (contestViewSystem.IsEnd && !ContestSoundPlayer.player.PlayingMusic)
					danceSection.FinishSection();
			}
			else if (!danceSection.IsActive)
			{
				if (ContestWork.IsMultiMode)
					RequestChangeSectionId(SectionID.WaitAsync);
				else
					RequestChangeSectionId(SectionID.PreLoadResult);
			}
		}
		private void UpdateResultSection(float deltaTime) {
			if (resultSection.UpdateSection(deltaTime))
				return;

			RequestChangeSectionId(resultSection.IsRestart ? SectionID.Restart : SectionID.End);
		}
		private global::System.Collections.IEnumerator IE_LoadResultResource() {
			ResultID resultID = dataModel.CalcContestResult();
			resultDataModel = dataModel.CreateModeResultData(resultID);
			// result unused, as in AppendOpeningResource (LoadSprite gets no variants)
			_ = Dpr.Message.MessageHelper.GetLocalizeVariants();
			resultDataModel.resultTitleSpr = resultDataModel.GetResultMessageSpr();
			resourceLoader.LoadSprite(dataModel.GetMedalTexturePath(), result => resultDataModel.medalSpr = result);
			resultDataModel.contestTitleSpr = dataModel.GetCategorySpr();
			resultDataModel.rankTitleSpr = dataModel.GetRankSpr();
			resourceLoader.RequestLoadAsset();
			objectManagerPtr.LoadResultFx();
			resultSection.LoadResource(resultID);
			while (resourceLoader.Loading)
				yield return null;

			while (!resultSection.IsReady)
				yield return null;

			RequestChangeSectionId(SectionID.Result);
		}
		private void OnLateUpdate(float deltaTime) {
			contestViewSystem.OnLateUpdate(deltaTime);
			wazaViewSystem.OnLateUpdate(deltaTime);
			LateUpdateSection();
			if (hasRequestChangeSectionID)
			{
				hasRequestChangeSectionID = false;
				currentSectionID = nextSectionID;
				DoNextSection();
				ContestUtils.EmitLog("Change SectionId : " + currentSectionID);
			}
		}
		private void DoNextSection() {
			switch (currentSectionID)
			{
				case SectionID.Opening:
					if (ContestWork.IsMultiMode && !network.CanPlayNetworkContest())
					{
						OnSessionError();
						return;
					}
					openingSection.StartSection();
					break;
				case SectionID.Visual:
					// inlined OnChangeSectionToVisual (= network.Reset(), flag 0x4cbdb58 @01c687bc); nothing else calls it
					if (ContestWork.IsMultiMode)
						OnChangeSectionToVisual();
					visualSection.StartSection();
					contestViewSystem.Play();
					objectManagerPtr.RegistVisualHeartUpdate();
					objectManagerPtr.SetAllPokemonAnimSound(true);
					objectManagerPtr.SetAudienceUpdateFlag(false);
					break;
				case SectionID.Dance:
					objectManagerPtr.RemoveVisualHeartUpdate();
					objectManagerPtr.SetAllPokemonAnimSound(false);
					objectManagerPtr.SetAudienceUpdateFlag(true);
					danceSection.StartSection();
					objectManagerPtr.PlayAllLightFxActive();
					break;
				case SectionID.PreLoadResult:
					if (dataModel.IsTutorial)
					{
						RequestChangeSectionId(SectionID.Result);
						return;
					}
					Sequencer.Start(IE_LoadResultResource());
					break;
				case SectionID.WaitAsync:
					OnChangeSectionWaitAsync();
					break;
				case SectionID.Result:
					resultSection.StartSection(resultDataModel);
					break;
				case SectionID.Restart:
					Sequencer.Start(IE_RestartContest());
					break;
			}
		}
		private void LateUpdateSection() {
			if (currentSectionID == SectionID.Dance)
				danceSection.OnLateUpdate();
		}
		private void ChangeSectionOpening() {
			objectManagerPtr.StartContest();
			objectManagerPtr.ResetDofParam(dataModel.CreateInitMainCameraDofTargetPos(), dataModel.CreateInitWazaCameraDofTargetPos());
			System.GC.Collect();
			RequestChangeSectionId(SectionID.Opening);
		}
		private void RequestChangeSectionId(global::Dpr.Contest.SectionID newSectionId) {
			if (hasRequestChangeSectionID)
			{
				ContestUtils.EmitLog(string.Format("Already Send Change SectionID Request : [{0}]", newSectionId), LogType.Warning);
				if (nextSectionID == SectionID.NetworkError || nextSectionID == SectionID.End)
				{
					ContestUtils.EmitLog(string.Format("nextSectionID is [{0}] - currentSectionID : [{1}]", nextSectionID, currentSectionID));
					return;
				}
			}
			ContestUtils.EmitLog(string.Format("SectionID Request : [{0}] -> [{1}]", nextSectionID, newSectionId));
			nextSectionID = newSectionId;
			hasRequestChangeSectionID = true;
		}
		private void OnFindCommand(global::Dpr.SequenceEditor.CommandNo commandNo, global::Dpr.Contest.ContestViewSystem viewSystem) {
			switch (commandNo)
			{
				case CommandNo.ContestHensin:
					objectManagerPtr.OnFindSeqCommand_ContestHensin();
					break;
				case CommandNo.ContestCaptureScene:
					dataModel.OnFindCaptureCommand(viewSystem);
					break;
				case CommandNo.SpecialMigawariVisible:
					resourceLoader.LoadMigawariModel(null);
					break;
			}
		}
		private void LoadMigawariModel() {
			resourceLoader.LoadMigawariModel(null);
		}
		private void OnPerformedCommand(global::Dpr.SequenceEditor.CommandNo commandNo, global::Dpr.Contest.ContestViewSystem viewSystem, global::Dpr.SequenceEditor.Macro macro) {
			switch (commandNo)
			{
				case CommandNo.ContestHideDanceUI:
					danceSection.HideDanceUI();
					break;
				case CommandNo.ContestLaunchUserWaza:
					danceSection.ForceLaunchContestWazaFromSeq();
					break;
				case CommandNo.ContestCaptureScene:
					dataModel.OnPerformCaptureCommand(viewSystem, macro);
					break;
			}
		}
		private void ForceStopContest() {
			contestViewSystem.SetPause(true);
			wazaViewSystem.SetPause(true);
			objectManagerPtr.Stop();
			openingSection.Stop();
			visualSection.Stop();
			danceSection.Stop();
			ContestSoundPlayer.Stop();
			if (MsgWindowManager.IsOpen)
				MsgWindowManager.CloseMsg();
		}
		private global::System.Collections.IEnumerator IE_RestartContest() {
			SmartPoint.Components.Fader.fillColor = Dpr.Battle.View.BattleViewDefine.BATTLE_FADE_OUT_FADER_COLOR;
			SmartPoint.Components.Fader.FadeOut();
			while (SmartPoint.Components.Fader.isBusy)
				yield return null;

			dataModel.ChangeTutorialSecondPlayData();
			visualSection.Setup(dataModel.GetMainBgmEventID(), contestViewSystem);
			yield return IE_ReloadTutorialSeq();

			yield return IE_LoadTutorialResource();

			ResetParam();
			while (!openingSection.IsReady)
				yield return null;

			System.GC.Collect();
			SmartPoint.Components.Fader.FadeIn();
			ChangeSectionOpening();
		}
		private global::System.Collections.IEnumerator IE_ReloadTutorialSeq() {
			contestViewSystem.UnloadAb();
			contestViewSystem.CMD_ACT_ContestMain_Start(dataModel.GetSequenceFilePath(), new ContestCameraSystem(contestViewSystem, objectManagerPtr.MainCamera), null, null);
			wazaViewSystem.UnloadAb();
			wazaViewSystem.CMD_ACT_WazaEffect_Start(dataModel.GetPlayerMonsNo(), dataModel.GetPlayerWazaNo(), dataModel.GetPlayerFormNo(),
				dataModel.GetPlayerPokeType1(), dataModel.GetPlayerPokeType2(), new ContestCameraSystem(wazaViewSystem, objectManagerPtr.WazaCamera), null, null);
			// one update + one frame only: resume state 1 finishes the coroutine (01c6be80)
			if (!contestViewSystem.IsReady || !wazaViewSystem.IsReady)
			{
				float deltaTime = Time.deltaTime;
				contestViewSystem.OnUpdate(deltaTime);
				wazaViewSystem.OnUpdate(deltaTime);
				yield return null;
			}
		}
		private global::System.Collections.IEnumerator IE_LoadTutorialResource() {
			openingSection.SetCategorySpr(dataModel.GetCategorySpr());
			resourceLoader.LoadNotesPatternData(dataModel.GetMusicFilePath(), result => dataModel.SetNotesData(result));
			resourceLoader.RequestLoadAsset();
			while (resourceLoader.Loading)
				yield return null;
		}
		private void ResetParam() {
			dataModel.SetSkillAnimDuration(wazaViewSystem.MaxTime);
			openingSection.ResetParam();
			visualSection.RestParam();
			danceSection.ResetParam(dataModel.GetDanceSectionData());
			resultSection.ResetParam();
			objectManagerPtr.ResetParam(dataModel.CreateInitMainCameraDofTargetPos(), dataModel.CreateInitWazaCameraDofTargetPos());
		}
		public ContestController() { }
	}
}
